select id, customer_id, plan, start_date, status, lead(monthly_fee, 1) over w_hist as next_monthly_fee, lead(monthly_fee, 1) over w_recent as next_monthly_fee_2, dense_rank() over (partition by customer_id, plan order by monthly_fee nulls last) as monthly_fee_dense_rank from subscriptions window w_hist as (partition by status order by monthly_fee, id), w_recent as (partition by customer_id order by start_date, id)
